INSERT INTO `quiz_questions` (`question_id`, `quiz_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `created_at`, `updated_at`, `explanation`) VALUES
(1, 1, 'According to NIST SP 800-145, which of the following is NOT one of the 5 essential characteristics of cloud computing?', 'On-demand self-service', 'Resource pooling', 'Guaranteed 100% uninterrupted uptime', 'Measured service', 'C', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'NIST SP 800-145 defines 5 characteristics: On-demand self-service, Broad network access, Resource pooling, Rapid elasticity, and Measured service. 100% uptime is never guaranteed due to realistic SLA limits.'),
(2, 1, 'What does the NIST characteristic \'Rapid Elasticity\' primarily mean?', 'The ability to run on multiple types of computer monitors', 'Capabilities can be elastically provisioned and released to scale rapidly outward and inward with demand', 'The speed at which physical optical cables transmit laser pulses', 'The ability of developers to work flexible remote work schedules', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Rapid elasticity allows compute and storage resources to expand or shrink dynamically to match consumer workload.'),
(3, 1, 'Which financial model change is most commonly associated with moving from on-premise data centers to the public cloud?', 'CapEx to OpEx', 'OpEx to CapEx', 'Fixed cost to zero cost', 'Elimination of all software licensing', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Cloud computing replaces large upfront Capital Expenditures (CapEx) with pay-as-you-go Operational Expenditures (OpEx).'),
(4, 1, 'Which organization authored the widely accepted standard definition for Cloud Computing in Special Publication 800-145?', 'IEEE', 'ISO', 'NIST (National Institute of Standards and Technology)', 'W3C', 'C', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'NIST (National Institute of Standards and Technology) published SP 800-145 in 2011, establishing the gold-standard cloud definitions.'),
(5, 1, 'In NIST terminology, what does \'Multi-Tenancy\' through resource pooling mean?', 'Multiple organizations renting office space in the same physical corporate building', 'Serving multiple customers from the same physical infrastructure with virtual isolation', 'A single computer running only one operating system with no network connection', 'Renting server racks exclusively for one tenant without virtualization', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Multi-tenancy pools physical resources to serve multiple customers dynamically while maintaining software-level boundaries.'),
(6, 1, 'What landmark event in 2006 marked the beginning of modern public Infrastructure as a Service (IaaS)?', 'The founding of Microsoft Corporation', 'The launch of Amazon Web Services (AWS) offering S3 and EC2', 'The invention of the World Wide Web by Tim Berners-Lee', 'The introduction of the Linux kernel version 1.0', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS launched S3 and EC2 in 2006, creating the modern commercial public IaaS cloud industry.'),
(7, 1, 'Which of the following best defines \'Measured Service\'?', 'Measuring the physical square footage of the cloud provider\'s datacenter', 'Monitoring and controlling resource usage with transparent metering and billing based on actual consumption', 'Measuring the length of fiber optic cables connecting servers', 'Counting the number of physical engineers employed on-site', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Measured service provides metering mechanisms (e.g. CPU hours, GB-months stored, network egress) for billing transparency.'),
(8, 1, 'What is the primary difference between traditional hosting and true cloud computing?', 'Cloud computing always runs on Windows operating systems', 'Cloud computing provides automated self-service, elasticity, and dynamic resource pooling', 'Traditional hosting is always free whereas cloud is expensive', 'Traditional hosting uses virtualization whereas cloud does not', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'True cloud satisfies all 5 NIST criteria, whereas traditional hosting involves static contracts and manual ticket-based provisioning.'),
(9, 1, 'Which pioneer famously predicted in 1961 that \'computation may someday be organized as a public utility\'?', 'Steve Jobs', 'John McCarthy', 'Bill Gates', 'Linus Torvalds', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Computer scientist John McCarthy predicted at MIT\'s centennial in 1961 that computation would become a public utility.'),
(10, 1, 'What is a major financial risk if an organization does not govern its cloud resource consumption?', 'Depreciation of virtual machines', 'Uncontrolled bill shock due to runaway idle or over-provisioned cloud instances', 'Physical wear and tear on developer laptops', 'Mandatory corporate tax audits on every API call', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Because cloud is OpEx and metered, unmonitored or unneeded instances can lead to unexpected high monthly bills (bill shock).'),
(11, 1, 'What does \'Broad Network Access\' guarantee in the cloud model?', 'Every citizen receives free internet connectivity', 'Cloud services can be accessed using standard protocols across diverse client platforms (phones, tablets, laptops, workstations)', 'All network traffic must travel via undersea satellite links', 'The cloud datacenter must be located within 5 kilometers of the user', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Broad network access ensures services are reachable over standard internet protocols through heterogeneous client devices.'),
(12, 1, 'Which term describes the practice of managing and optimizing cloud operational expenditures?', 'DevSecOps', 'FinOps', 'SysAdmin', 'NetOps', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'FinOps (Financial Operations) is the cultural and operational practice that brings financial accountability to cloud spending.'),
(13, 1, 'Under an on-premise model, what is a typical hardware procurement lead time for new physical servers?', 'Instantaneous (less than 1 millisecond)', 'Weeks to months (purchase orders, shipping, racking, cabling)', 'Always exactly 24 hours', 'Zero days because servers grow automatically', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Procuring physical hardware takes weeks or months to approve, ship, rack, wire, and configure, contrasting with minutes in the cloud.'),
(14, 1, 'Which of the following is an example of an on-demand self-service action?', 'Submitting a paper requisition form to an IT committee and waiting 3 weeks', 'Deploying an Amazon EC2 virtual machine using a CLI command or management console without human approval', 'Physically driving to a datacenter to insert a RAM stick', 'Calling a phone hotline to request a reboot', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'On-demand self-service means spinning up or tearing down resources programmatically via API or console without human gatekeepers.'),
(15, 1, 'Why does cloud resource pooling lead to economies of scale?', 'Providers purchase hardware in massive bulk and achieve higher average server utilization across diverse customer time zones', 'Providers don\'t pay for electricity', 'Cloud servers do not require processors or memory chips', 'Providers use unpaid volunteer software engineers', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Aggregating diverse customer workloads enables cloud hyper-scalers to purchase hardware at deep bulk discounts and run at higher hardware utilization.'),
(16, 1, 'What is \'over-provisioning\' in traditional computing environments?', 'Buying excess physical hardware to survive rare peak usage spikes, leaving resources idle 90% of the time', 'Running out of RAM during normal operations', 'Writing code with too many nested loops', 'Hiring too many technical writers for software manuals', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Traditional data centers must buy enough physical servers for peak Black Friday traffic, leaving expensive hardware idle during off-peak periods.'),
(17, 1, 'How does cloud computing address the problem of over-provisioning and under-provisioning?', 'By enforcing a fixed limit of 100 users per company', 'By utilizing dynamic auto-scaling to match resource allocation directly with instantaneous demand', 'By shutting down user applications whenever traffic increases', 'By converting all user traffic into email messages', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Elastic auto-scaling expands capacity during demand spikes and contracts it when demand subsides, avoiding both waste and crashes.'),
(18, 1, 'Which company pioneered software delivery over the web via SaaS in 1999?', 'Salesforce', 'Netflix', 'Uber', 'Spotify', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Salesforce pioneered the modern SaaS model in 1999 by delivering customer relationship management (CRM) software directly via a web browser.'),
(19, 1, 'What does \'Sunk Cost\' mean in the context of on-premise datacenter equipment?', 'Hardware submerged in liquid cooling tanks', 'Money already spent that cannot be recovered regardless of future decisions', 'The cost of undersea fiber optic communication cables', 'The electricity consumed during a network power outage', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Sunk costs are capital investments already committed to physical hardware that cannot be refunded if business priorities change.'),
(20, 1, 'Which of the following is considered an Operational Expenditure (OpEx)?', 'Monthly AWS billing invoice for compute and storage consumed', 'Buying a 50,000 square foot plot of land to build a datacenter', 'Purchasing a $250,000 diesel backup generator for a server room', 'Purchasing a 5-year permanent server rack chassis', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Monthly utility-style subscription invoices for cloud services are categorized as operational expenditures (OpEx).'),
(21, 2, 'What does Horizontal Scaling (Scale Out) involve in cloud architecture?', 'Adding more CPUs and RAM to a single existing virtual machine', 'Adding more machine instances in parallel to distribute the workload', 'Increasing the physical height of a server rack', 'Migrating from Linux to Windows operating systems', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Horizontal scaling (scaling out) adds more instances or nodes behind a load balancer to handle traffic increases.'),
(22, 2, 'What is Vertical Scaling (Scale Up)?', 'Upgrading the hardware specs (CPU, RAM, disk) of a single server', 'Adding 10 additional micro instances to an Auto Scaling Group', 'Moving a server from the first floor to the top floor of a building', 'Setting up a content delivery network', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Vertical scaling increases the computing capacity of an individual machine by adding more CPU cores, RAM, or storage.'),
(23, 2, 'What is a Single Point of Failure (SPOF)?', 'A software testing methodology used by QA teams', 'Any single component whose malfunction terminates the entire system\'s operation', 'A backup generator running in a datacenter', 'A high-speed optical network switch with redundant links', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A Single Point of Failure is a critical element of a system which, if it fails, will trigger the failure of the whole system.'),
(24, 2, 'What does \'Recovery Point Objective\' (RPO) measure?', 'The length of time required to boot up a new server', 'The maximum acceptable amount of data loss expressed in time prior to the disaster', 'The financial cost of purchasing replacement hard drives', 'The number of employees permitted in a server room', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'RPO defines the maximum tolerable period during which data might be lost due to a catastrophic failure.'),
(25, 2, 'What does \'Recovery Time Objective\' (RTO) measure?', 'The maximum allowable downtime before a business process or application must be restored', 'The time it takes to write a line of code', 'The speed at which data travels through optical fiber', 'The warranty duration of physical cloud servers', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'RTO defines the target duration of time within which a service must be restored after a disruption.'),
(26, 2, 'How much annual downtime is permitted under a \'four nines\' (99.99%) High Availability SLA?', 'Approximately 3.65 days', 'Approximately 8.76 hours', 'Approximately 52.6 minutes', 'Zero seconds under all circumstances', 'C', '2026-10-25 17:28:08', '2026-10-26 07:13:57', '99.99% availability allows only 0.01% downtime per year: 365.25 days * 24 hrs * 60 min * 0.0001 = ~52.56 minutes.'),
(27, 2, 'In public cloud platforms like AWS, what is an Availability Zone (AZ)?', 'A country where cloud sales reps are physically present', 'One or more discrete datacenters with independent power, cooling, and networking within a region', 'A software licensing zone with reduced tax rates', 'The range of IP addresses assigned to student accounts', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'An Availability Zone consists of one or more isolated physical datacenters engineered to be insulated from failures in other AZs.'),
(28, 2, 'What is the primary advantage of deploying an application across Multi-AZ (Multiple Availability Zones)?', 'It eliminates all software coding bugs', 'It ensures the system survives if a disaster strikes a single physical datacenter', 'It makes the cloud subscription 100% free of charge', 'It stops malicious hackers from viewing public websites', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Multi-AZ architectures provide high availability and automatic failover if an entire physical datacenter suffers a catastrophic outage.'),
(29, 2, 'Which Disaster Recovery strategy features the lowest RTO and RPO but carries the highest operational cost?', 'Backup and Restore', 'Pilot Light', 'Warm Standby', 'Multi-Site Active-Active', 'D', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Active-Active runs redundant production traffic simultaneously across multiple geographic locations with sub-second failover, at highest cost.'),
(30, 2, 'What role does a Load Balancer play in a horizontally scalable cloud system?', 'It distributes incoming client traffic evenly across multiple healthy backend application instances', 'It regulates electrical voltage entering server motherboards', 'It deletes unused files on student hard drives', 'It encrypts physical hard drives using biometric locks', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Load balancers act as the reverse-proxy traffic cop, distributing incoming requests across healthy target server instances.'),
(31, 2, 'What is a \'Fault Domain\' in cloud infrastructure design?', 'A section of an application codebase with failing unit tests', 'A physical grouping of infrastructure hardware that shares common single points of failure like power and network switches', 'A domain name that has expired and cannot be registered', 'An invalid user account blocked by an administrator', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Fault domains share common physical hardware elements (such as power racks or switches); separating instances across fault domains prevents joint failure.'),
(32, 2, 'In the context of Disaster Recovery, what does a \'Pilot Light\' approach mean?', 'Turning off all lights inside the physical datacenter to conserve energy', 'Replicating critical core data in real-time, while keeping compute infrastructure stopped until disaster recovery is triggered', 'Running only a small pilot group of test users on beta software', 'Using solar powered battery backups for server fans', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'In a Pilot Light setup, the database and core state are continuously replicated, but compute servers are provisioned or started only during a disaster.'),
(33, 2, 'Which architectural characteristic is essential for web applications to scale horizontally without session conflicts?', 'Stateful local memory storage on the server hard drive', 'Stateless architecture with centralized session stores (e.g. Redis or database)', 'Hard-coding user IP addresses into application source code', 'Enforcing single-threaded execution on all backend workers', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Stateless architecture allows any backend instance to handle any incoming request because state is decoupled into a shared data store.'),
(34, 2, 'What happens when a vertically scaled server reaches the physical motherboards maximum RAM capacity?', 'The server creates virtual quantum RAM automatically', 'It hits a hardware ceiling and cannot scale up any further without complete architecture redesign', 'The operating system converts CPU cache into hard disk space', 'The cloud provider provides free server hardware upgrades', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Vertical scaling is inherently limited by physical hardware limits (motherboard sockets, chipset ceilings), leading to hard scalability walls.'),
(35, 2, 'What is the primary role of the Frontend plane in cloud architecture?', 'Directly managing SAN disk arrays inside datacenters', 'Interfacing with the client through UI, mobile apps, DNS, and API gateways', 'Configuring kernel hypervisor schedulers', 'Executing database backup restore scripts', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'The frontend plane represents the user-facing interface, edge endpoints, and delivery mechanisms that connect users to backend services.'),
(36, 2, 'Which of the following is an example of an architectural Single Point of Failure (SPOF)?', 'A database cluster with automated multi-region active replication', 'A web tier utilizing three redundant servers across two Availability Zones', 'A single centralized database server with no standby replicas or automated backups', 'A DNS service configured with multiple global anycast IP addresses', 'C', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A single centralized database server with no failover replica will bring the entire system down if it crashes, making it a classic SPOF.'),
(37, 2, 'If an enterprise requires an RPO of 5 minutes, what does this dictate for their data backup strategy?', 'They can back up their database once a month', 'They must continuously replicate or snapshot data at least every 5 minutes', 'They only need paper printouts of financial records', 'They can accept losing up to 48 hours of customer data', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'An RPO of 5 minutes means the business cannot tolerate losing more than 5 minutes of data, requiring continuous replication or <=5 min snapshots.'),
(38, 2, 'What is the difference between a Cloud Region and an Edge Location / Point of Presence (PoP)?', 'Regions host full compute, database, and storage platforms; Edge Locations cache content close to end users for lower latency', 'Regions are for students; Edge Locations are for faculty', 'Edge locations contain nuclear power plants', 'Regions only exist in North America', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Regions provide full cloud services, while Edge Locations (Points of Presence) are distributed worldwide primarily for CDN caching and low-latency delivery.'),
(39, 2, 'Why do distributed cloud microservices utilize message queues (e.g., SQS, RabbitMQ, Kafka)?', 'To slow down user requests so servers do not overheat', 'To decouple microservices asynchronously and absorb sudden traffic spikes without dropped requests', 'To replace all relational databases permanently', 'To restrict internet access to authorized corporate IP addresses', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Message queues decouple producers and consumers, buffering requests so systems can process workloads asynchronously without dropping messages.'),
(40, 2, 'What is the mathematical availability percentage for \'five nines\'?', '95.555%', '99.005%', '99.999%', '99.990%', 'C', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Five nines is 99.999% availability, allowing no more than 5.26 minutes of total unplanned downtime per calendar year.'),
(41, 3, 'Which cloud service model provides the customer with the highest degree of administrative control over the operating system and networking?', 'Software as a Service (SaaS)', 'Platform as a Service (PaaS)', 'Infrastructure as a Service (IaaS)', 'Function as a Service (FaaS)', 'C', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'IaaS gives the customer full administrative access to install, configure, and patch guest operating systems and network routes.'),
(42, 3, 'Which of the following is the best example of a Software as a Service (SaaS) application?', 'Amazon EC2', 'Google Workspace (formerly G Suite)', 'Google App Engine', 'OpenStack', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Google Workspace is a complete turnkey SaaS suite delivered via web browser without infrastructure maintenance by the user.'),
(43, 3, 'Under the Shared Responsibility Model for an IaaS deployment (e.g. AWS EC2), who is responsible for patching the guest operating system?', 'The Cloud Service Provider (e.g. AWS)', 'The customer / organization deploying the virtual machine', 'The hardware manufacturer of the server', 'The local electrical utility company', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'In IaaS, the customer is fully responsible for security \'IN\' the cloud, including installing guest OS security patches and updates.'),
(44, 3, 'What does the cloud provider manage in a Platform as a Service (PaaS) offering?', 'Only the physical security of the datacenter doors', 'The hardware, virtualization, operating system, runtime environment, and middleware', 'The customer\'s business bank accounts', 'Nothing; the customer manages all software layers', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'PaaS providers manage the OS, runtime execution environment, web servers, and physical hardware, leaving only application code to the developer.'),
(45, 3, 'Which of the following services is classified as Platform as a Service (PaaS)?', 'AWS Elastic Beanstalk', 'Amazon S3', 'Microsoft Office 365', 'Physical bare-metal server', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS Elastic Beanstalk provides a managed platform where developers upload application code and the platform manages deployment and scaling.'),
(46, 3, 'What is the primary defining billing characteristic of Serverless Function as a Service (FaaS)?', 'Paying a flat fee of $1,000 every calendar month', 'Billed strictly for the exact compute execution duration (milliseconds) while code runs, with $0 cost when idle', 'Billed per physical processor chip inside the datacenter', 'Billed only if your code has zero bugs', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Serverless FaaS (e.g. AWS Lambda) executes code on-demand and bills per millisecond of compute time consumed, incurring no cost when idle.'),
(47, 3, 'In the \'Pizza as a Service\' analogy, which cloud model corresponds to \'Dining at a Restaurant\' where everything is provided for you?', 'On-Premises', 'IaaS', 'PaaS', 'SaaS', 'D', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'In the famous analogy, dining out represents SaaS because the customer simply enjoys the final product without cooking, cleaning, or setup.'),
(48, 3, 'What security duty remains the responsibility of the customer across ALL cloud models (IaaS, PaaS, and SaaS)?', 'Physical security guard patrols around the server cages', 'User authentication, identity access management, and data governance', 'Replacing faulty hard drives in storage arrays', 'Updating BIOS firmware on server motherboards', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Regardless of service model, the customer always retains responsibility for managing their user credentials, access rights, and data classification.'),
(49, 3, 'Why might a legacy enterprise application NOT be suitable for PaaS without significant code refactoring?', 'PaaS environments do not support the English language', 'The application may rely on specific underlying OS kernel drivers, registry hacks, or local file system state that PaaS restricts', 'PaaS is illegal for commercial organizations', 'PaaS does not support networking or internet protocols', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'PaaS environments enforce standardized containerized runtimes and restrict direct OS kernel modifications or persistent local file system states.'),
(50, 3, 'Which service model offers the highest developer velocity for building new web and mobile backends quickly?', 'IaaS', 'PaaS', 'Bare-metal on-premise servers', 'Mainframe punch cards', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'PaaS allows developers to write code and deploy immediately without wasting engineering cycles managing servers, OS updates, or load balancers.'),
(51, 3, 'What is an architectural concern known as \'Cold Start\' in Serverless FaaS platforms?', 'Servers physically freezing in arctic datacenters', 'Initial latency delay when a function container is initialized from an idle state upon receiving a request', 'The time required to compile C++ code', 'A server failing to boot because of battery discharge', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A cold start occurs when an event triggers a serverless function that has no active container in memory, causing initialization latency.'),
(52, 3, 'Which of the following is an example of an Infrastructure as a Service (IaaS) provider offering?', 'Salesforce CRM', 'Microsoft Azure Virtual Machines', 'Canva Graphic Design', 'Dropbox Web App', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Azure Virtual Machines provide raw compute instances with selectable operating systems, falling squarely under IaaS.'),
(53, 3, 'Who is responsible for physical datacenter security in a public cloud model?', 'The Cloud Service Provider (CSP)', 'The customer\'s local security team', 'The end users accessing the website', 'The United Nations IT council', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'The Cloud Service Provider is exclusively responsible for physical perimeter security, biometric locks, and surveillance of datacenters.'),
(54, 3, 'What is a potential disadvantage of utilizing Platform as a Service (PaaS)?', 'Having to buy physical server racks', 'Potential vendor lock-in due to platform-specific configuration APIs and runtime constraints', 'Inability to run any JavaScript code', 'Paying for unused idle servers 24 hours a day', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'PaaS platforms often introduce proprietary deployment scripts and architectural hooks that make migrating to another cloud vendor challenging.'),
(55, 3, 'If a company uses Salesforce for CRM, what tier of the cloud service stack is it utilizing?', 'Hardware as a Service (HaaS)', 'Software as a Service (SaaS)', 'Infrastructure as a Service (IaaS)', 'Database as a Service (DBaaS)', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Salesforce CRM is a turnkey business software application delivered over the internet, representing Software as a Service (SaaS).'),
(56, 3, 'In IaaS, what tool does the customer use to configure virtual network boundaries and subnets?', 'Virtual Private Cloud (VPC)', 'Physical patch cables', 'Hardware soldering iron', 'SaaS email client', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Customers use Virtual Private Clouds (VPCs) in IaaS to define virtual network topology, subnets, route tables, and gateways.'),
(57, 3, 'Which service model is best suited if you must run a custom Linux distribution with a patched proprietary kernel?', 'SaaS', 'PaaS', 'IaaS', 'FaaS', 'C', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Only IaaS provides the low-level administrative control required to boot custom operating system images and customized kernels.'),
(58, 3, 'What does the phrase \'Security OF the Cloud\' encompass?', 'Protecting the global infrastructure, hardware, and physical facilities that run cloud services', 'Writing customer web application SQL queries securely', 'Configuring customer database user passwords', 'Creating strong passwords for student email accounts', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', '\'Security OF the Cloud\' belongs to the CSP and protects physical facilities, hypervisors, and global network backbones.'),
(59, 3, 'What does the phrase \'Security IN the Cloud\' encompass?', 'Cleaning dust off server fans in the provider datacenter', 'Customer data, identity management, firewall configuration, OS patching, and network traffic protection', 'Building concrete blast walls around provider buildings', 'Replacing undersea optical fiber repeaters', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', '\'Security IN the Cloud\' is customer responsibility, including customer data protection, IAM, firewall ports, and guest OS security.'),
(60, 3, 'Why is Software as a Service (SaaS) considered cost-effective for standard office productivity tools?', 'It eliminates in-house server hardware, deployment engineering, and ongoing maintenance overhead', 'It allows employees to work with no internet access forever', 'It grants the company ownership of the cloud provider\'s datacenters', 'It replaces all computer monitors with virtual reality headsets', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'SaaS removes the expensive overhead of running email servers, database clusters, and dedicated IT maintenance staff for standard apps.'),
(61, 4, 'Which cloud deployment model provides infrastructure for exclusive use by a single organization?', 'Public Cloud', 'Private Cloud', 'Community Cloud', 'Hybrid Cloud', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Private cloud infrastructure is operated solely for a single organization, providing strict data isolation and control.'),
(62, 4, 'What defines a Public Cloud deployment model?', 'The cloud datacenter is owned by the government and free to all citizens', 'Infrastructure owned and operated by a third-party commercial provider delivered over the public internet to multiple tenants', 'Any website that does not require a password to access', 'A server running open-source Linux software', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Public clouds (e.g., AWS, Azure) are owned by commercial hyper-scalers and deliver multi-tenant resources over the network.'),
(63, 4, 'What is \'Cloud Bursting\' in a Hybrid Cloud architecture?', 'A server overheating and exploding due to high CPU load', 'Running baseline workloads on a private cloud and automatically bursting into a public cloud during demand spikes', 'Deleting all cloud files when a storage quota is exceeded', 'A hacker attacking multiple cloud providers simultaneously', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Cloud bursting leverages public cloud elasticity on-demand when private cloud capacity reaches its ceiling during peak traffic.'),
(64, 4, 'Which cloud deployment model is designed for organizations with shared mission goals, security requirements, or compliance regulations?', 'Private Cloud', 'Community Cloud', 'Public Cloud', 'Personal Cloud', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Community clouds are shared by organizations with common regulatory, compliance, or mission needs (e.g., government agencies, hospitals).'),
(65, 4, 'What is AWS GovCloud an example of?', 'A public social media platform', 'A community/specialized cloud environment meeting US government compliance standards (e.g. FedRAMP, ITAR)', 'A gaming network for government employees', 'A private cloud running inside a presidential office', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS GovCloud is an isolated cloud region tailored for US government agencies and contractors adhering to strict federal regulations.'),
(66, 4, 'Which connectivity method provides a dedicated, physical fiber optic link bypassing the public internet to connect on-premises data centers to AWS?', 'Public Wi-Fi Hotspot', 'AWS Direct Connect', 'Standard dial-up modem', 'Bluetooth Low Energy', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS Direct Connect provides dedicated private physical fiber links between customer data centers and AWS for low latency and high bandwidth.'),
(67, 4, 'What is Azure\'s equivalent service to AWS Direct Connect?', 'Azure ExpressRoute', 'Azure Virtual Network Gateway', 'Azure QuickLink', 'Azure FiberDirect', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Azure ExpressRoute creates private, dedicated connections between Azure datacenters and on-premises infrastructure without traversing the public internet.'),
(68, 4, 'What is a primary disadvantage of a Private Cloud compared to a Public Cloud?', 'Lower control over security policies', 'High upfront Capital Expenditures (CapEx) and continuous in-house operational maintenance', 'Total inability to run virtualization software', 'Having to share physical hard drives with external competitors', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Private clouds require heavy capital expenditure to buy physical servers, storage, switches, cooling, and staff to maintain them.'),
(69, 4, 'What is the primary benefit of a Multi-Cloud strategy?', 'It guarantees that the company will never pay any cloud bills', 'Mitigating vendor lock-in, enabling best-of-breed tool selection, and increasing disaster resilience across providers', 'Eliminating the need to write software code', 'Merging all cloud providers into a single corporate monopoly', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Multi-cloud prevents single-vendor dependency, leverages distinct provider strengths, and hedges against systemic provider-wide outages.'),
(70, 4, 'In a hybrid cloud setup, why might a hospital keep patient electronic medical records (EMR) on-premises while running web appointment scheduling in the public cloud?', 'Because public cloud servers cannot display appointment calendars', 'To satisfy strict HIPAA / data residency compliance regulations for patient data while leveraging public cloud elasticity for web traffic', 'Because on-premise servers are always 100 times faster than cloud servers', 'To avoid paying for hospital electricity', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Hybrid cloud enables data tiering: keeping strictly regulated data on private infrastructure while running scalable web portals in public cloud.'),
(71, 4, 'What technology allows containerized applications to run seamlessly across on-premise private clouds, AWS, Azure, and Google Cloud?', 'Microsoft Paint', 'Kubernetes and Docker container standards', 'Analog telephone cables', 'Proprietary database triggers', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Standardized container engines (Docker) and orchestrators (Kubernetes) package applications with their dependencies for write-once, run-anywhere portability.'),
(72, 4, 'What is a significant drawback of connecting an on-premises datacenter to a cloud provider via an IPSec VPN over the public internet?', 'Data cannot be encrypted', 'Throughput and latency fluctuate unpredictably based on public internet network congestion', 'IPSec VPNs are prohibited by international law', 'It requires installing physical satellites on user roofs', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'While IPSec VPNs are encrypted, public internet routing is subject to variable latency, jitter, packet loss, and ISP congestion.'),
(73, 4, 'Which open-source software platform is widely used to deploy and orchestrate Private Cloud infrastructure on-premises?', 'OpenStack', 'WordPress', 'VLC Media Player', 'Adobe Photoshop', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'OpenStack is the leading open-source cloud computing platform for building private clouds across commodity hardware pools.'),
(74, 4, 'What is a \'Noisy Neighbor\' problem in a Public Cloud environment?', 'Loud construction noise outside the user\'s home office', 'Another tenant on the same physical host monopolizing shared I/O or network bandwidth, degrading your application\'s performance', 'Music played by datacenter maintenance staff', 'A compiler generating excessive warning messages', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'In multi-tenant public clouds, a noisy neighbor is a co-located tenant whose heavy resource consumption starves neighboring VMs of I/O.'),
(75, 4, 'How do hypervisors and modern public cloud providers prevent the noisy neighbor effect?', 'By banning all users from running databases', 'By implementing strict hardware resource throttling, dedicated tenancy options, and modern offloaded nitro hypervisors', 'By disconnecting servers whenever utilization exceeds 20%', 'By using only single-core processors', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Cloud hypervisors enforce strict CPU/network quotas, and offer dedicated instances and hardware-level isolation to prevent starvation.'),
(76, 4, 'Which deployment model is most common for early-stage startups that need to launch applications with minimum initial runway?', 'Private Cloud on leased physical mainframes', 'Public Cloud', 'Community Cloud', 'Building an underground nuclear bunker datacenter', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Public clouds require zero capital investment and offer free tier credits, making them the standard choice for cash-conscious startups.'),
(77, 4, 'What is the primary operational trade-off of adopting a Multi-Cloud architecture?', 'Increased operational complexity, fragmented monitoring, and cross-cloud networking data egress costs', 'Faster internet speeds for all users worldwide', 'Total immunity from all software bugs', 'Automatic reduction of all developer salaries', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Managing multiple clouds fragments operational tooling, requires engineers to master different platforms, and incurs high data egress fees between clouds.'),
(78, 4, 'What is \'Data Sovereignty\'?', 'The legal principle that digital data is subject to the laws and governance of the geographic country in which it is physically stored', 'The right of a database administrator to delete tables without warning', 'A cryptocurrency token traded on public exchanges', 'The encryption key used by an operating system kernel', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Data sovereignty requires organizations to comply with the legal and privacy regulations of the nation where the physical datacenter resides.'),
(79, 4, 'Which tool allows declarative Infrastructure as Code (IaC) provisioning across AWS, Azure, and Google Cloud using a single configuration syntax?', 'HashiCorp Terraform', 'Microsoft Word', 'Adobe Illustrator', 'Windows Calculator', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Terraform is an open-source Infrastructure as Code tool that enables multi-cloud provisioning using declarative HashiCorp Configuration Language (HCL).'),
(80, 4, 'Why might a sovereign government establish a dedicated Community Cloud rather than using standard public cloud regions?', 'To ensure that all physical hardware, network links, and operations personnel meet strict national security clearance mandates', 'Because commercial public clouds cannot connect to the internet', 'To prevent commercial software from being used by citizens', 'Because community clouds are always run on solar powered calculators', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Dedicated community/gov clouds ensure physical isolation and restrict administrative personnel to verified citizens with security clearances.'),
(81, 5, 'What is another standard term for a Hypervisor?', 'Virtual Machine Monitor (VMM)', 'Dynamic Host Configuration Protocol (DHCP)', 'Basic Input Output System (BIOS)', 'Network Interface Card (NIC)', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Hypervisor and Virtual Machine Monitor (VMM) are synonymous terms for the software layer managing virtual machines.'),
(82, 5, 'What defines a Type 1 Hypervisor?', 'It runs as an application inside an existing host desktop operating system', 'It runs directly on the bare-metal physical hardware without an underlying host operating system', 'It only works on smartphones and mobile devices', 'It requires mechanical floppy disks to boot', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Type 1 (Bare-Metal) hypervisors install directly onto the physical server hardware, providing maximum performance and efficiency.'),
(83, 5, 'Which of the following is an example of a Type 1 (Bare-Metal) Hypervisor?', 'Oracle VM VirtualBox', 'VMware Workstation', 'VMware ESXi', 'Microsoft Word', 'C', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'VMware ESXi is an enterprise-grade Type 1 bare-metal hypervisor installed directly onto physical servers.'),
(84, 5, 'Which of the following is an example of a Type 2 (Hosted) Hypervisor?', 'Oracle VM VirtualBox', 'Linux KVM bare-metal', 'Citrix Hypervisor / XenServer', 'AWS Nitro Card', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Oracle VirtualBox runs as an application inside a host operating system (Windows/macOS/Linux), making it a Type 2 hypervisor.'),
(85, 5, 'What hardware extensions did Intel and AMD introduce to accelerate CPU virtualization?', 'DirectX and OpenGL', 'Intel VT-x and AMD-V', 'PCI-Express and USB 3.0', 'RGB LED controllers', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Intel VT-x and AMD-V provide silicon-level instruction set extensions enabling hypervisors to run guest OS kernels securely and swiftly.'),
(86, 5, 'In Paravirtualization, how does the guest operating system interact with the hypervisor?', 'It does not know it is virtualized and emulates old hardware devices', 'It is modified with specialized drivers (e.g. virtio) to make direct \'hypercalls\' to the hypervisor', 'It bypasses the hypervisor and takes exclusive physical ownership of the CPU', 'It sends analog audio beeps to the motherboard speaker', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Paravirtualization modifies the guest OS kernel with enlightened drivers (virtio) that make hypercalls directly to the hypervisor.'),
(87, 5, 'What is \'Live Migration\' (such as VMware vMotion or KVM live migration)?', 'Migrating an employee from one office desk to another', 'Moving an active, running virtual machine from one physical server to another with zero perceptible downtime', 'Powering off a server, unplugging the hard drive, and physically carrying it to a new room', 'Translating code from Python to Java', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Live migration transfers the active execution memory state of a running VM across physical hosts without interrupting service.'),
(88, 5, 'What is \'Server Consolidation\'?', 'Combining multiple underutilized physical servers into virtual machines on a single powerful physical host', 'Physically soldering two servers together in a server rack', 'Deleting 50% of an organization\'s databases to save space', 'Restricting all employees to using only one email account', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Server consolidation replaces dozens of underutilized physical servers with VMs on high-density physical hardware, saving power and space.'),
(89, 5, 'What phenomenon is known as \'VM Sprawl\'?', 'Virtual machines physically expanding in size inside a datacenter rack', 'The proliferation of unmanaged, forgotten, or abandoned virtual machines consuming cluster computing resources', 'An error where a virtual machine fails to allocate an IP address', 'A computer virus that infects hypervisors', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'VM sprawl occurs when virtual machines are spun up easily but never decommissioned, draining compute and storage resources.'),
(90, 5, 'What is the function of Extended Page Tables (EPT) or Nested Page Tables (NPT) in modern processors?', 'Hardware-assisted translation from guest physical memory to host physical memory to eliminate memory virtualization overhead', 'Allowing web browsers to open infinite tabs', 'Printing book pages at double speed', 'Formatting hard drives with FAT32 filesystems', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'EPT (Intel) and NPT (AMD) are hardware memory management unit (MMU) features that accelerate virtual-to-physical memory address translation.'),
(91, 5, 'Which file format is standard for QEMU/KVM virtual disk images with copy-on-write capabilities?', '.MP3', '.QCOW2', '.DOCX', '.EXE', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'QCOW2 (QEMU Copy-On-Write 2) is the primary virtual disk format for KVM, supporting thin provisioning, compression, and snapshots.'),
(92, 5, 'What is a Virtual Machine Snapshot?', 'A photograph taken of the physical datacenter room', 'A point-in-time copy of a virtual machine\'s disk state and memory, allowing instant rollback in case of error', 'A screenshot of the desktop background wallpaper', 'An audio recording of the server fan spinning', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A snapshot captures the exact state and data of a virtual machine at a specific instant, providing a rapid rollback mechanism.'),
(93, 5, 'Why are Type 2 Hypervisors generally unsuitable for enterprise cloud production environments?', 'They cannot run on Intel chips', 'They introduce severe performance overhead by running on top of an unnecessary host operating system layer', 'They only work when disconnected from the internet', 'They do not support keyboard inputs', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Type 2 hypervisors incur double context switches and OS scheduling overhead because they run inside a general-purpose host OS.'),
(94, 5, 'In x86 computer architecture, which ring level possesses the highest hardware privileges for kernel operations?', 'Ring 3', 'Ring 2', 'Ring 1', 'Ring 0', 'D', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Ring 0 is the most privileged execution level on x86 processors, reserved for operating system kernels and bare-metal hypervisors.'),
(95, 5, 'What is an AMI in the context of Amazon Web Services?', 'Amazon Machine Image — a pre-configured template containing the OS, software, and configuration to launch an EC2 instance', 'Automated Management Interface', 'Advanced Motherboard Interconnect', 'Analog Modem Identification', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'An AMI (Amazon Machine Image) is a packaged virtual machine template that includes the OS, application server, and default configurations.'),
(96, 5, 'What network action occurs during the final phase of a Live VM Migration so switches route traffic to the new host?', 'A reboot of all physical routers in the building', 'The new host broadcasts a Gratuitous ARP (GARP) packet to update the network switches\' MAC address forwarding tables', 'The user must manually type a new IP address into their browser', 'The network cable must be manually unplugged and re-plugged', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A Gratuitous ARP broadcast updates the Layer 2 switch forwarding tables immediately to associate the VM\'s MAC address with the new physical port.'),
(97, 5, 'What does \'Thin Provisioning\' mean for a virtual disk?', 'The disk only consumes physical storage space as data is actually written to it, rather than allocating all capacity upfront', 'The hard drive is physically made of ultra-thin aluminum foil', 'Only thin clients can read data from the disk', 'The disk automatically deletes files after 7 days', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Thin provisioning allocates storage space on-demand as blocks are written, optimizing physical disk capacity across virtual machines.'),
(98, 5, 'Which hypervisor technology is integrated directly into the core Linux kernel?', 'KVM (Kernel-based Virtual Machine)', 'VirtualBox', 'VMware Workstation', 'Parallels Desktop', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'KVM (Kernel-based Virtual Machine) is built directly into the mainline Linux kernel, converting Linux into a Type 1 bare-metal hypervisor.'),
(99, 5, 'What is the primary benefit of Open Virtualization Format (OVF)?', 'It allows open-source games to run faster', 'It provides an open, vendor-neutral standard for packaging and distributing virtual appliances across different hypervisors', 'It makes physical computer cases transparent', 'It encrypts video streaming services', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'OVF is a platform-independent packaging format that allows virtual appliances to be imported across VMware, VirtualBox, KVM, and Xen.'),
(100, 5, 'How does AWS Nitro architecture modernize traditional hypervisor virtualization?', 'By eliminating all virtual machines and returning to physical mainframes', 'By offloading virtualization tasks (networking, EBS storage, security) to dedicated hardware ASIC cards, freeing almost 100% of host CPU/RAM for guest VMs', 'By running the entire AWS cloud on smartphones', 'By using liquid nitrogen to cool individual processors', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS Nitro offloads hypervisor overhead (storage I/O, VPC networking, security) onto dedicated PCIe Nitro cards, yielding near-pure bare metal performance.'),
(101, 6, 'Which cloud storage type functions like an unformatted physical raw hard drive attached to a virtual machine?', 'Object Storage', 'Block Storage', 'File Storage', 'Cold Archival Storage', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Block storage (e.g. AWS EBS) provides raw storage blocks that can be formatted with any filesystem (ext4, NTFS) for OS and DB use.');
INSERT INTO `quiz_questions` (`question_id`, `quiz_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `created_at`, `updated_at`, `explanation`) VALUES
(102, 6, 'Which of the following is the premier example of an Object Storage service?', 'AWS Elastic File System (EFS)', 'Amazon Elastic Block Store (EBS)', 'Amazon Simple Storage Service (Amazon S3)', 'Linux SWAP partition', 'C', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Amazon S3 is the industry benchmark for hyperscale object storage, storing data as discrete objects in buckets over HTTP APIs.'),
(103, 6, 'What network protocols are typically used to mount cloud File Storage across multiple virtual machines?', 'NFS (Network File System) and SMB (Server Message Block)', 'SMTP and POP3', 'BGP and OSPF', 'SSH and Telnet', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Cloud file storage services (e.g. AWS EFS, Azure Files) utilize standard NFS (Linux) and SMB/CIFS (Windows) protocols.'),
(104, 6, 'How much durability is Amazon S3 Standard designed to provide for stored objects?', '90.0%', '99.0%', '99.999999999% (11 nines)', '100.0% with zero hardware failures forever', 'C', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Amazon S3 Standard is engineered for 99.999999999% (11 nines) of annual data durability by redundantly storing objects across multiple AZs.'),
(105, 6, 'What is the maximum file size for a single object in Amazon S3?', '5 Gigabytes', '500 Megabytes', '5 Terabytes', 'Unlimited single object size', 'C', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Individual objects in Amazon S3 can range from 0 bytes up to a maximum of 5 Terabytes (uploaded via multipart upload for >5GB).'),
(106, 6, 'What does the CAP Theorem state regarding distributed data systems?', 'All cloud computers are permanently secure', 'A distributed system can guarantee at most two out of Consistency, Availability, and Partition Tolerance simultaneously', 'Storage capacity doubles every 18 months', 'Every database must run on MySQL', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Eric Brewer\'s CAP Theorem proves a distributed system cannot achieve Consistency, Availability, and Partition Tolerance all at once.'),
(107, 6, 'Because network partitions (P) are physically inevitable in distributed networks, what fundamental architectural trade-off must designers make?', 'Choosing between CP (Consistency over Availability) or AP (Availability over Consistency)', 'Choosing between Windows or macOS', 'Choosing between keyboards or mice', 'Choosing between electricity or solar power', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'When network communication between nodes breaks, systems must decide whether to stop writes to ensure consistency (CP) or keep running with potential stale data (AP).'),
(108, 6, 'In an Eventual Consistency model, what happens immediately after a write operation?', 'The entire database crashes and restarts', 'A read request immediately following the write might temporarily return stale data until all replicas synchronize', 'All other users are logged out permanently', 'The write is rejected and deleted', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Eventual consistency allows asynchronous replication; reads immediately following a write may return stale data until replicas catch up.'),
(109, 6, 'Which storage service is specifically optimized for cold archiving compliance records with retrieval times of 3 to 5 hours or 12 hours at lowest cost?', 'Amazon S3 Glacier / S3 Glacier Deep Archive', 'AWS EBS Provisioned IOPS', 'RAM cache', 'Local NVMe instance store', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'S3 Glacier and Glacier Deep Archive provide ultra-low-cost cold storage designed for long-term data retention with delayed retrieval.'),
(110, 6, 'What is an S3 Lifecycle Rule?', 'A policy that automatically transitions objects between storage tiers or deletes them based on age', 'A biological law governing the lifespan of servers', 'A warranty contract for datacenter cooling fans', 'A rule requiring users to change passwords every 30 days', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Lifecycle configuration rules automate data migration (e.g. from Standard to Infrequent Access to Glacier) and expiration based on age.'),
(111, 6, 'Why is Block Storage (EBS) preferred over Object Storage (S3) for running relational database engines like MySQL or PostgreSQL?', 'Object storage is too expensive for text files', 'Databases require low-latency random read/write I/O operations and filesystem-level file locking that object storage does not support', 'MySQL does not run on Linux', 'Block storage does not require any passwords', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Relational databases modify discrete 8KB/16KB page blocks randomly on disk; S3 requires rewriting the entire object on every change.'),
(112, 6, 'How do clients interact with and retrieve files from Object Storage?', 'Via standard HTTP/HTTPS REST API requests (e.g., GET, PUT, DELETE) using URLs', 'Using a physical SATA ribbon cable', 'By inserting a USB thumb drive into the cloud server', 'Through a BIOS setup menu', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Object storage is accessed via standard web protocols (HTTP/HTTPS) using RESTful endpoints and unique object URLs.'),
(113, 6, 'What is the primary difference between AWS EBS and AWS EFS?', 'EBS is block storage attached to a single VM; EFS is shared file storage that can be mounted simultaneously by hundreds of VMs', 'EBS is free; EFS costs $10,000 per month', 'EBS is for Windows only; EFS is for Android phones only', 'EBS does not support encryption', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'EBS attaches as a block device to one EC2 instance at a time, whereas EFS is a distributed NFS file system mounted by hundreds of instances concurrently.'),
(114, 6, 'What is IOPS in storage performance benchmarking?', 'Input/Output Operations Per Second — measuring how many read/write operations a storage drive can perform each second', 'Internet Online Protocol Standard', 'Internal Operating Power Supply', 'Integrated Optical Processing Speed', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'IOPS measures the number of discrete read or write operations a storage volume can process per second, critical for database responsiveness.'),
(115, 6, 'What is \'Instance Store\' (ephemeral storage) on AWS EC2?', 'Temporary block-level storage physically attached to the host server that is wiped and lost if the instance stops or terminates', 'Permanent storage backed up to magnetic tape', 'A retail store that sells cloud merchandise', 'A database table that stores user passwords', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Instance Store provides ultra-high-speed temporary scratch storage physically located on the host server, but data is lost when the instance is stopped.'),
(116, 6, 'Which of the following is considered \'Unstructured Data\' ideally suited for cloud object storage?', 'High-resolution video files, audio recordings, and medical imaging DICOM files', 'A strict 10-column relational SQL table of bank accounts', 'A CSV spreadsheet containing employee ID numbers', 'A primary key index file in Oracle DB', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Unstructured data refers to rich media files, PDFs, videos, and images that lack a rigid tabular schema, making them ideal for object storage.'),
(117, 6, 'What is the PACELC theorem an extension of?', 'Moore\'s Law', 'The CAP Theorem — adding Latency (L) vs Consistency (C) trade-offs during normal operating conditions (Else - E)', 'Newton\'s Third Law of Motion', 'Amdahl\'s Law of Parallel Computing', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Daniel Abadi\'s PACELC theorem extends CAP: if Partition (P), choose Availability (A) or Consistency (C); Else (E), choose Latency (L) or Consistency (C).'),
(118, 6, 'What does S3 Object Versioning protect against?', 'High electricity bills', 'Accidental deletions and unintended overwrites by retaining historical versions of every object', 'Server motherboards catching fire', 'Slow internet speeds', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'S3 Versioning preserves multiple versions of an object in the same bucket, allowing quick recovery from unintended overwrites or deletions.'),
(119, 6, 'What is the purpose of S3 Pre-Signed URLs?', 'Allowing users temporary secure access to download or upload a specific private S3 object without granting them AWS credentials', 'Signing an electronic lease for datacenter property', 'Registering a domain name with ICANN', 'Translating URLs into physical street addresses', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Pre-signed URLs grant time-limited cryptographic permissions to upload or download a private S3 object directly from the client.'),
(120, 6, 'In distributed database replication, what is a \'Split-Brain\' scenario?', 'When a programmer forgets how their code works', 'When a network partition causes two isolated clusters of nodes to both believe they are the active primary, accepting conflicting writes', 'When a processor chip cracks physically in half', 'When an operating system runs two web browsers at the same time', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Split-brain occurs when network partition isolates nodes, causing multiple subsets to elect new leaders independently, generating data divergence.'),
(121, 7, 'What does VPC stand for in cloud computing?', 'Virtual Private Cloud', 'Virtual Public Connection', 'Variable Protocol Controller', 'Verified Personal Computer', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'VPC stands for Virtual Private Cloud, a logically isolated virtual network dedicated to your cloud account.'),
(122, 7, 'In CIDR notation, how many total IP addresses are in a /24 network block?', '65,536', '256', '16', '1,024', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A /24 IPv4 CIDR block leaves 32 - 24 = 8 bits for host addresses, yielding 2^8 = 256 total IP addresses.'),
(123, 7, 'How many IP addresses does AWS reserve for internal networking purposes in every subnet?', '0 addresses', '5 addresses (Network, VPC router, DNS, future use, and broadcast)', '100 addresses', '1 address', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS reserves the first 4 and last 1 IP addresses in every subnet (e.g., .0, .1, .2, .3, and .255 in a /24), leaving 251 usable.'),
(124, 7, 'What distinguishes a Public Subnet from a Private Subnet in a VPC?', 'Public subnets use Windows; private subnets use Linux', 'A public subnet has a route table entry pointing directly to an Internet Gateway (IGW)', 'Public subnets are completely unencrypted', 'Private subnets do not require IP addresses', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A subnet is classified as public if its route table directs default outbound internet traffic (0.0.0.0/0) to an Internet Gateway.'),
(125, 7, 'What is the purpose of a NAT Gateway in a cloud VPC?', 'To allow public internet users to hack database servers', 'To allow instances in a private subnet to initiate outbound connections to the internet (for updates) while preventing unsolicited inbound connections from the internet', 'To speed up audio streaming for video games', 'To assign physical MAC addresses to server racks', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A NAT Gateway allows instances in private subnets to reach out to the internet (e.g. for software patches) while blocking inbound connections.'),
(126, 7, 'What is the primary operational difference between Security Groups and Network Access Control Lists (NACLs)?', 'Security Groups are stateful (instance level); NACLs are stateless (subnet level)', 'Security Groups only work on Mondays; NACLs work every day', 'Security Groups require hardware cables; NACLs run in software', 'NACLs are stateful; Security Groups are stateless', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Security Groups are stateful firewalls operating at the instance/ENI level; NACLs are stateless boundary filters operating at the subnet level.'),
(127, 7, 'If you permit inbound traffic on port 443 in a stateful Security Group, what outbound rule is required for the response traffic?', 'You must create an outbound rule permitting port 443 explicitly', 'No outbound rule is needed because stateful firewalls automatically allow response traffic for permitted inbound sessions', 'You must restart the virtual machine', 'You must configure a NAT Gateway', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Because Security Groups are stateful, return traffic for an established inbound connection is automatically tracked and permitted out.'),
(128, 7, 'Which type of firewall rules are supported by Network Access Control Lists (NACLs)?', 'ALLOW rules only', 'Both explicit ALLOW and explicit DENY rules, evaluated in numerical order', 'DENY rules only', 'No rules; NACLs are open by default', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'NACLs support both ALLOW and DENY rules, evaluating rules in ascending numerical order until a match occurs.'),
(129, 7, 'Which AWS Load Balancer operates at Layer 7 of the OSI model and can route traffic based on HTTP request path or host headers?', 'Classic Load Balancer (CLB)', 'Application Load Balancer (ALB)', 'Network Load Balancer (NLB)', 'Gateway Load Balancer (GWLB)', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Application Load Balancers (ALB) operate at Layer 7, providing path-based, host-based, query-string, and HTTP header routing.'),
(130, 7, 'Which Load Balancer operates at Layer 4 (TCP/UDP) and is engineered for ultra-high throughput with tens of millions of requests per second?', 'Application Load Balancer (ALB)', 'Network Load Balancer (NLB)', 'Session Load Balancer', 'Content Routing Balancer', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Network Load Balancers (NLB) operate at Layer 4 (Transport layer), delivering sub-millisecond latencies and handling extreme traffic spikes.'),
(131, 7, 'What is Amazon Route 53?', 'A physical highway in Seattle, Washington', 'A highly available and scalable cloud Domain Name System (DNS) web service', 'A network firewall for filtering DDoS attacks', 'A server monitoring tool for CPU temperatures', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Amazon Route 53 is AWS\'s authoritative cloud DNS service (named after TCP/UDP port 53 used by DNS).'),
(132, 7, 'What is the primary function of a Content Delivery Network (CDN) such as Amazon CloudFront?', 'To replace all database servers with flat text files', 'To cache static and dynamic web content at global edge locations close to users, reducing latency and origin server load', 'To compile C++ source code in the cloud', 'To physically mail hard drives to customer offices', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'CDNs cache content at geographically distributed Edge Points of Presence, serving users from the closest location for low latency.'),
(133, 7, 'What does \'Non-Transitive\' mean in VPC Peering?', 'Traffic travels in one direction only', 'If VPC A is peered with VPC B, and VPC B is peered with VPC C, VPC A cannot communicate with VPC C through VPC B without a direct peering link', 'VPC peering does not support IPv4', 'Peering connections automatically expire after 1 hour', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'VPC peering is non-transitive; edge routing through intermediate VPCs is prohibited. Direct peering or a Transit Gateway is required.'),
(134, 7, 'What AWS service acts as a centralized cloud hub router connecting thousands of VPCs and on-premises networks in a hub-and-spoke model?', 'AWS Transit Gateway', 'Internet Gateway', 'NAT Instance', 'Route 53 Resolver', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS Transit Gateway is a central cloud router that simplifies networking by replacing complex mesh peering with a hub-and-spoke topology.'),
(135, 7, 'What is AWS PrivateLink (VPC Endpoints)?', 'A private chat application for AWS developers', 'A mechanism to privately connect your VPC to supported AWS services (like S3) without traversing the public internet', 'A public URL shortener', 'A tool to expose private databases directly to the public web', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS PrivateLink / VPC Endpoints allow instances in a private subnet to securely communicate with services like S3 over the private AWS backbone.'),
(136, 7, 'What is an Elastic IP address (EIP) in AWS?', 'An IP address that stretches over physical cables', 'A static, public IPv4 address allocated to your account that can be rapidly remapped to different instances during failures', 'A private IP address that changes every 5 minutes', 'An IP address assigned to mobile phones only', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'An Elastic IP is a static public IPv4 address designed for dynamic cloud redirection, masking instance failures by remapping.'),
(137, 7, 'In a typical secure 3-tier web architecture, where should the relational database (e.g. MySQL) be placed?', 'In the public subnet with an Internet Gateway route', 'In a private subnet with no direct route to the Internet Gateway, accessible only by the application tier', 'On a public CDN edge location', 'Directly on an unencrypted DNS server', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Databases must reside in isolated private subnets, shielded from direct internet access and reachable only via application servers.'),
(138, 7, 'What Route 53 routing policy routes user DNS requests to the resource that provides the lowest network latency?', 'Simple Routing', 'Latency-Based Routing', 'Geolocation Routing', 'Weighted Routing', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Latency-based routing directs users to the cloud region that delivers the fastest response time based on network telemetry.'),
(139, 7, 'What is the primary role of a Route Table in a VPC?', 'A table listing employee names and phone numbers', 'A set of rules (routes) that determine where network packets from subnets or gateways are directed', 'A database table that records SQL transactions', 'A hardware table used to assemble physical servers', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Route tables contain destination CIDR blocks and target gateways/interfaces, dictating packet paths inside the virtual network.'),
(140, 7, 'What is an Ephemeral Port range, and why is it important in stateless NACL rule configuration?', 'Ports 1-1024 used for secure web browsing', 'Short-lived client port ranges (typically 1024-65535) used for return traffic, which stateless NACLs must permit on outbound rules', 'Physical USB ports on a server front panel', 'Virtual ports that only exist during leap years', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Clients use ephemeral ports (1024-65535) as temporary source ports; stateless firewalls must allow return traffic on this range.'),
(141, 8, 'What security principle dictates that users and services should only be granted the minimum permissions necessary to perform their jobs?', 'Principle of Maximum Availability', 'Principle of Least Privilege (PoLP)', 'Principle of Infinite Redundancy', 'Principle of Open Access', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'The Principle of Least Privilege states that identities should receive only the strictly necessary access permissions, minimizing breach impact.'),
(142, 8, 'Under the Cloud Shared Responsibility Model, who is responsible for the physical security of the cloud provider\'s datacenters?', 'The Cloud Service Provider (CSP)', 'The customer organization', 'The local municipal police', 'The individual software developer', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'The Cloud Service Provider owns security \'OF\' the cloud, including physical datacenter perimeter fences, biometric controls, and guards.'),
(143, 8, 'Which authentication mechanism requires a user to supply at least two independent types of credentials before granting access?', 'Single Sign-On (SSO)', 'Multi-Factor Authentication (MFA)', 'Basic HTTP Authentication', 'Anonymous Guest Access', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'MFA requires two or more distinct factors (e.g., knowledge factor like password + possession factor like a hardware token).'),
(144, 8, 'Why should developers use IAM Roles with instance profiles rather than embedding long-term API access keys inside application source code?', 'IAM Roles make code compile faster', 'IAM Roles provide short-lived temporary security credentials that rotate automatically, preventing credential leaks if code is compromised', 'IAM Roles are free whereas API keys cost $100 each', 'IAM Roles allow unlimited public database access', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'IAM Roles use temporary STS credentials, eliminating static API keys that could otherwise be accidentally leaked in public git repositories.'),
(145, 8, 'What encryption standard is universally utilized as the benchmark for symmetric data encryption at rest in modern clouds?', 'MD5', 'AES-256 (Advanced Encryption Standard 256-bit)', 'ROT13', 'DES 56-bit', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AES-256 is the gold-standard symmetric encryption algorithm utilized by hyperscale cloud providers for disk and database encryption at rest.'),
(146, 8, 'What is \'Envelope Encryption\' in cloud cryptography?', 'Mailing encryption keys inside physical paper envelopes', 'Encrypting plaintext data with a unique Data Key, and then encrypting that Data Key with a root Customer Master Key (CMK)', 'Hiding passwords inside HTML comments', 'Wrapping server cables in aluminum foil', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Envelope encryption encrypts data with a Data Key, which is itself encrypted by a Master Key, combining performance with secure key management.'),
(147, 8, 'What protocol is used to secure Data in Transit over the web?', 'Transport Layer Security (TLS / HTTPS)', 'Telnet', 'Plain HTTP over port 80', 'FTP', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'TLS (typically version 1.2 or 1.3) encrypts network communications in transit, preventing eavesdropping and tampering.'),
(148, 8, 'What is AWS CloudTrail?', 'A hiking trail located near Amazon headquarters', 'A service that records every API call and user action made in an AWS account for governance and auditing', 'A tool to track delivery of physical Amazon packages', 'A programming language used for cloud microservices', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS CloudTrail audits all API activities across your cloud account, logging caller identity, timestamps, source IPs, and request parameters.'),
(149, 8, 'What does GDPR stand for, and what major right does it grant individuals regarding their data?', 'General Data Protection Regulation — grants the \'Right to Be Forgotten\' (data erasure) and strict consent controls', 'Global Data Processing Resource', 'Government Distributed Protocol Requirement', 'General Database Protection Routine', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'GDPR is the European Union\'s data privacy regulation giving individuals legal control over their personal data, including the right to deletion.'),
(150, 8, 'What US regulation protects the privacy and confidentiality of Protected Health Information (PHI)?', 'PCI-DSS', 'HIPAA (Health Insurance Portability and Accountability Act)', 'DMCA', 'OSHA', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'HIPAA establishes federal standards to protect sensitive patient health information from being disclosed without consent.'),
(151, 8, 'What is the single most common cause of security breaches in public cloud environments according to major cybersecurity reports?', 'Physical theft of hard drives from datacenters', 'Customer misconfigurations (e.g. overly permissive IAM policies or public S3 buckets)', 'Solar flares corrupting server memory', 'Physical damage to undersea fiber cables', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Industry analysts (such as Gartner) note that nearly 99% of cloud security failures through 2025 are customer misconfigurations.'),
(152, 8, 'What is a DDoS (Distributed Denial of Service) attack?', 'An attacker physically cutting power lines to a data center', 'An attempt to overwhelm an online service with a flood of illegitimate traffic originating from thousands of distributed botnet devices', 'A database error caused by a missing semicolon', 'A hardware failure of an individual CPU core', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A DDoS attack attempts to exhaust network bandwidth or compute capacity by swamping target servers with distributed traffic.'),
(153, 8, 'Which AWS managed service provides automated DDoS protection for web applications?', 'AWS Shield', 'AWS Lambda', 'Amazon S3', 'Amazon RDS', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS Shield provides managed DDoS protection, with Shield Standard enabled automatically for all customers and Shield Advanced offering expanded defense.'),
(154, 8, 'What does Role-Based Access Control (RBAC) do?', 'Assigns permissions to roles based on organizational responsibilities, rather than managing individual user privileges directly', 'Assigns administrative permissions based on employee age', 'Rotates physical computer desks every week', 'Enforces password changes every 10 minutes', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'RBAC simplifies access governance by assigning permissions to functional roles (e.g. Developer, BillingAdmin), which users are mapped into.'),
(155, 8, 'What is a Web Application Firewall (WAF) designed to inspect and block?', 'Physical fire in a server room', 'Application layer (Layer 7) web exploits like SQL Injection (SQLi) and Cross-Site Scripting (XSS)', 'Hardware voltage spikes in power supplies', 'Unplugged Ethernet cables', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A WAF monitors HTTP/HTTPS traffic to defend web applications against common web exploits such as SQL injection and XSS.'),
(156, 8, 'What is a Hardware Security Module (HSM)?', 'A physical computing device that safeguards and manages cryptographic keys and performs cryptographic operations inside tamper-resistant hardware', 'A cooling fan for graphic processing units', 'A type of fiber optic network cable', 'A monitor cable adapter', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'An HSM is a dedicated, tamper-resistant physical crypto processor designed to securely generate and store cryptographic keys.'),
(157, 8, 'What audit report verifies a service provider\'s operational controls over security, availability, and confidentiality across an extended observation period?', 'SOC 2 Type II', 'Driver\'s license record', 'Standard invoice receipt', 'Git commit history', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A SOC 2 Type II report evaluates and attests to the operational effectiveness of security and availability controls over a period of time (typically 6-12 months).'),
(158, 8, 'What is the primary risk of using the Root Account of a cloud provider for day-to-day administrative activities?', 'It has unrestricted, irrevocable access to all resources and billing; compromise gives attackers complete ownership of the entire organization', 'It slows down internet connection speeds', 'It causes servers to run out of disk space', 'It cancels all existing customer credit cards', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'The root account possesses absolute authority; compromising root credentials gives an attacker full power to delete all resources and data.'),
(159, 8, 'What does \'Confidential Computing\' (Data in Use encryption) provide?', 'Hardware-based Trusted Execution Environments (TEEs) that keep data encrypted in RAM even while active processing occurs', 'NDAs signed by datacenter cleaning staff', 'Turning off computer monitors when leaving desks', 'Encrypting only outgoing email messages', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Confidential computing isolates sensitive data inside hardware-enforced memory enclaves, protecting data in use from hypervisors and host admins.'),
(160, 8, 'What is AWS GuardDuty?', 'An armed security officer stationed at AWS gates', 'An intelligent threat detection service that continuously monitors AWS accounts using machine learning and threat intelligence feeds', 'A backup battery for desktop computers', 'A compiler for Rust applications', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Amazon GuardDuty is an AI-powered threat detection service analyzing VPC Flow Logs, CloudTrail, and DNS logs to uncover malicious behavior.'),
(161, 9, 'What is the primary architectural difference between a Docker container and a traditional Virtual Machine?', 'Containers require physical hardware ribbons', 'Containers share the host operating system kernel and isolate user space, whereas VMs virtualize hardware and run complete separate guest operating systems', 'Containers can only run Windows 95', 'VMs do not require processors', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Containers share the host OS kernel and use kernel namespaces/cgroups for isolation, avoiding the heavy overhead of separate guest OS kernels.'),
(162, 9, 'Which Linux kernel feature provides process, network, and filesystem isolation for containers?', 'Namespaces', 'BIOS', 'FAT32', 'Swap partitions', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Linux namespaces (PID, NET, MNT, IPC, UTS, USER) partition kernel resources so each container sees its own isolated view of the system.'),
(163, 9, 'Which Linux kernel feature is used to enforce resource limits (e.g. capping CPU and RAM usage) on containers?', 'Control Groups (cgroups)', 'X11 Window System', 'DNS', 'BASH aliases', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Control Groups (cgroups) allocate and limit hardware resources (CPU, memory, disk I/O, network bandwidth) among process groups.'),
(164, 9, 'What is a Dockerfile?', 'A digital photograph of a shipping vessel', 'A text configuration file containing instructions to automate the building of a Docker container image', 'A spreadsheet of monthly cloud bills', 'An encrypted virus database', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A Dockerfile is a recipe of declarative steps (FROM, RUN, COPY, CMD) used by Docker to assemble container image layers.'),
(165, 9, 'In Docker, what is the layer property that allows multiple running containers to share the exact same base image in memory safely?', 'Copy-on-Write (CoW) / Union File System', 'Direct Memory Access', 'Analog Tape Mirroring', 'Read-Only BIOS Chips', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Union filesystems share immutable base image layers and allocate an ephemeral copy-on-write layer on top for each running container.'),
(166, 9, 'What is the smallest deployable computing unit in Kubernetes?', 'Node', 'Pod', 'Cluster', 'Virtual Machine', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A Pod is the fundamental atomic building block in Kubernetes, wrapping one or more tightly coupled containers sharing network and storage.'),
(167, 9, 'In Kubernetes architecture, what distributed key-value store holds the entire cluster state and configuration data?', 'etcd', 'Redis', 'MySQL', 'MongoDB', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'etcd is the highly available, consistent distributed key-value store used as the single source of truth for all Kubernetes cluster state.'),
(168, 9, 'What is the role of the kube-scheduler in a Kubernetes cluster?', 'To schedule employee lunch breaks', 'To select the most appropriate worker node to run newly created or unscheduled Pods based on resource requirements', 'To compile software code into binaries', 'To send email receipts to customers', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'The kube-scheduler monitors newly created Pods with no assigned node and selects an optimal worker node for them to run on.'),
(169, 9, 'Which Kubernetes resource manages stateless application replicas and enables zero-downtime rolling updates?', 'Deployment', 'Namespace', 'ConfigMap', 'Secret', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A Kubernetes Deployment provides declarative updates for Pods, orchestrating rolling rollouts and rollbacks without service disruption.'),
(170, 9, 'What is the purpose of a Kubernetes Service abstraction?', 'To clean server rooms on weekends', 'To provide a permanent, stable IP address and DNS name that load balances traffic across dynamic, ephemeral Pods', 'To calculate billing taxes', 'To format hard drives on worker nodes', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Because Pods are frequently created and destroyed, Services provide a static IP and DNS name to route traffic reliably to healthy Pods.'),
(171, 9, 'What is AWS Lambda?', 'A physical microchip manufactured by Amazon', 'A serverless compute service that runs code in response to events and automatically manages the underlying compute resources', 'A relational database engine', 'A satellite ground station', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS Lambda is Amazon\'s premier Function as a Service (FaaS) platform, running code triggered by events with zero server administration.'),
(172, 9, 'In serverless computing, what is a \'Cold Start\'?', 'A computer freezing during winter weather', 'The latency delay experienced when a cloud provider boots up a new container runtime environment to service an incoming request', 'Rebooting a desktop computer with a power switch', 'Running a code compiler without internet access', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Cold start refers to the initial initialization delay when a serverless function is triggered after being idle or scaling up new instances.'),
(173, 9, 'How can developers mitigate serverless cold-start latency for latency-sensitive production APIs?', 'Using AWS Lambda Provisioned Concurrency to keep pre-warmed execution environments ready', 'Writing 50,000 lines of unused code', 'Turning off HTTPS encryption', 'Using mechanical hard drives', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Provisioned Concurrency keeps a configured number of serverless execution environments initialized and ready to respond in double-digit milliseconds.'),
(174, 9, 'What billing model does AWS Lambda utilize?', 'Pay strictly per millisecond of compute execution time and number of requests, with zero cost when idle', 'Flat monthly fee of $500', 'Hourly rental fees regardless of whether code runs', 'Annual upfront licensing contracts', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Lambda charges based on the number of requests and duration (metered in 1-millisecond increments), with zero idle standby cost.'),
(175, 9, 'Which Kubernetes component runs on every worker node and ensures that containers described in PodSpecs are running and healthy?', 'kubelet', 'etcd', 'kube-controller-manager', 'CloudTrail', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'The kubelet is the primary node agent that registers the node with the API server and watches PodSpecs to keep containers running.'),
(176, 9, 'What is a Container Registry?', 'A legal courthouse for shipping containers', 'A centralized repository for storing, tagging, and distributing compiled container images (e.g. Docker Hub, Amazon ECR)', 'A log file on an operating system', 'A spreadsheet of user passwords', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A container registry (like Docker Hub or AWS ECR) stores versioned container images for download during deployment.'),
(177, 9, 'Why must serverless functions be designed as \'Stateless\'?', 'Because serverless containers are ephemeral and can be destroyed immediately after execution completes', 'Because serverless does not support math equations', 'Because serverless code cannot access databases', 'Because stateful code is prohibited by law', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Serverless containers are created and terminated dynamically; any state stored locally in memory or local disk is lost upon teardown.'),
(178, 9, 'What is Kubernetes Ingress?', 'A tool to delete worker nodes', 'An API object that manages external HTTP and HTTPS routing to services within the cluster, offering SSL termination and path routing', 'A hardware network switch installed in a datacenter', 'A command-line text editor', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Ingress manages external HTTP/S access to internal cluster services, providing routing rules, hostname matching, and SSL/TLS termination.'),
(179, 9, 'Which command in a Dockerfile defines the default executable and parameters to run when the container starts?', 'CMD or ENTRYPOINT', 'FROM', 'MAINTAINER', 'EXPOSE', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'ENTRYPOINT and CMD specify the default process and arguments executed when a container spins up.'),
(180, 9, 'In microservices architectures, what is the role of an API Gateway in front of Serverless functions?', 'It acts as the single entrypoint for clients, handling routing, SSL termination, rate limiting, and mapping HTTP requests to FaaS triggers', 'It converts web pages into paper printouts', 'It powers off cloud datacenters at night', 'It replaces all frontend CSS stylesheets', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'An API Gateway provides a managed front door for applications, translating external HTTP REST/WebSocket requests into serverless invocations.'),
(181, 10, 'Which public cloud platform was launched first in 2006, pioneering the modern commercial IaaS market?', 'Microsoft Azure', 'Google Cloud Platform', 'Amazon Web Services (AWS)', 'IBM Cloud', 'C', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS launched in 2006 with S3 and EC2, giving it a four-year first-mover advantage over its closest hyperscale competitors.'),
(182, 10, 'What is Microsoft Azure\'s equivalent service to Amazon EC2?', 'Azure Virtual Machines', 'Azure Blob Storage', 'Azure Functions', 'Azure DevOps', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Azure Virtual Machines provides on-demand raw compute instances, corresponding directly to Amazon EC2.'),
(183, 10, 'What is Google Cloud Platform\'s equivalent service to Amazon S3?', 'Google Cloud Storage (GCS)', 'Google Compute Engine', 'Google BigQuery', 'Google App Engine', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Google Cloud Storage (GCS) is GCP\'s hyperscale RESTful object storage service, matching Amazon S3.'),
(184, 10, 'Which major enterprise identity and directory service gives Microsoft Azure a distinct competitive advantage in corporate environments?', 'Microsoft Entra ID (formerly Azure Active Directory)', 'Google Accounts', 'Apple ID', 'Linux PAM', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Microsoft Entra ID is the enterprise identity backbone; organizations already using Windows and Office 365 integrate seamlessly with Azure.'),
(185, 10, 'Which Google Cloud database service was the first globally distributed database to achieve both External Consistency (ACID) and High Availability using atomic clocks?', 'Cloud SQL', 'Cloud Spanner', 'Cloud Bigtable', 'Cloud Datastore', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Google Cloud Spanner uses TrueTime (atomic clocks and GPS antennas) to deliver synchronized global ACID transactions across continents.'),
(186, 10, 'What is Google Cloud\'s premier serverless, petabyte-scale data warehouse service for analytical SQL queries?', 'BigQuery', 'Amazon Athena', 'Azure Synapse', 'MySQL Workbench', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Google BigQuery is a serverless, highly scalable enterprise data warehouse that executes SQL queries across petabytes in seconds.'),
(187, 10, 'What is the name of Microsoft Azure\'s globally distributed multi-model NoSQL database that offers 5 customizable consistency levels?', 'Azure Cosmos DB', 'Azure SQL Database', 'Azure Blob DB', 'Azure Data Lake', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Azure Cosmos DB is a globally distributed NoSQL database offering multi-master replication and five well-defined consistency choices.'),
(188, 10, 'What managed Kubernetes service is offered by Google Cloud Platform?', 'Amazon EKS', 'Google Kubernetes Engine (GKE)', 'Azure AKS', 'OpenShift', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Google Kubernetes Engine (GKE) is GCP\'s managed K8s service, benefiting from Google\'s original development of Kubernetes.'),
(189, 10, 'Which cloud provider has an exclusive partnership to host OpenAI\'s large language model APIs (e.g. GPT-4)?', 'Microsoft Azure', 'Amazon Web Services', 'Alibaba Cloud', 'Oracle Cloud', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Microsoft\'s multi-billion dollar partnership with OpenAI provides Azure exclusive hosting and integration for GPT-4 via Azure OpenAI Service.'),
(190, 10, 'What custom AI processor silicon did Google engineer specifically for training and inferencing large neural networks in the cloud?', 'TPU (Tensor Processing Unit)', 'Intel Pentium', 'AMD Ryzen', 'Nvidia GeForce 256', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Google designed custom ASIC Tensor Processing Units (TPUs) specifically to accelerate machine learning workloads in Google Cloud.'),
(191, 10, 'What is Amazon\'s custom ARM-based server CPU family designed for high efficiency and lower cloud compute costs?', 'AWS Graviton', 'AWS Nitro', 'AWS Xeon', 'AWS Snapdragon', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS Graviton processors are custom 64-bit ARM CPUs engineered by Amazon delivering up to 40% better price-performance over x86 chips.'),
(192, 10, 'What open-source Infrastructure as Code tool enables provisioning across AWS, Azure, and GCP using a unified declarative syntax?', 'HashiCorp Terraform', 'AWS CloudFormation', 'Azure Bicep', 'Google Deployment Manager', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Terraform supports multiple cloud providers via provider plugins, allowing engineers to write multi-cloud IaC in HCL.'),
(193, 10, 'What is \'Vendor Lock-in\'?', 'A physical lock placed on a datacenter server rack', 'A situation where a customer becomes dependent on a single cloud vendor\'s proprietary technologies, making migration prohibitively costly', 'A vendor refusing to sell computers to students', 'A contract requiring developers to work exclusively on Windows', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Vendor lock-in occurs when using proprietary APIs or schemas makes switching to a rival cloud platform economically or technically painful.'),
(194, 10, 'Which of the following database choices minimizes cloud vendor lock-in for a web application?', 'Standard open-source PostgreSQL running on managed database instances', 'Amazon DynamoDB with proprietary AWS SDK calls', 'Azure Cosmos DB Table API', 'Google Cloud Spanner', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Open-source PostgreSQL runs identically on AWS RDS, Azure Database for PostgreSQL, Google Cloud SQL, or on-premises servers.'),
(195, 10, 'What is Google Cloud\'s serverless container platform that automatically scales arbitrary HTTP containers to zero?', 'Cloud Run', 'Cloud Build', 'Cloud Composer', 'Cloud Shell', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'GCP Cloud Run allows developers to deploy arbitrary Docker containers that run serverlessly, scaling up on requests and down to zero when idle.'),
(196, 10, 'What is Azure Arc?', 'A video game released by Microsoft', 'A hybrid and multi-cloud management platform that extends Azure governance, services, and policies to on-premises, AWS, and GCP environments', 'A physical electrical battery for Azure servers', 'A web browser developed for Linux', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Azure Arc simplifies governance by projecting resources located outside Azure (on-prem or other clouds) into the Azure Resource Manager.'),
(197, 10, 'How does Google Cloud organize resources hierarchically for identity and billing management?', 'Organization -> Folders -> Projects -> Resources', 'User -> Password -> Database -> Table', 'Single flat list of IP addresses', 'Alphabetical order by file size', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Google Cloud structures resources in a clear four-tier hierarchy: Organization root, departmental Folders, individual Projects, and raw Resources.'),
(198, 10, 'Which cloud provider is historically recognized for offering the largest total number of distinct, specialized cloud services and features?', 'Amazon Web Services (AWS)', 'DigitalOcean', 'Linode', 'Heroku', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS features the broadest and deepest product catalog in the cloud industry, with over 200 fully featured services.'),
(199, 10, 'What is AWS Fargate?', 'A serverless compute engine for containers that works with both Amazon ECS and EKS without requiring you to manage EC2 worker instances', 'A physical toll booth outside Amazon datacenters', 'A network firewall for filtering malware', 'A tool to monitor electrical wattage', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS Fargate runs containers serverlessly, removing the operational overhead of provisioning, configuring, and scaling virtual machine clusters.'),
(200, 10, 'Why might a large enterprise deliberately choose a Multi-Cloud architecture despite higher operational overhead?', 'To eliminate single-vendor dependency, satisfy government regulations, and leverage specialized best-of-breed services from different providers', 'Because single cloud providers are prohibited from having more than 10 customers', 'To avoid using internet cables', 'Because multi-cloud is completely free of charge', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Enterprises adopt multi-cloud to prevent lock-in, meet regulatory risk diversification rules, and use specific strengths like GCP AI and Azure Identity.'),
(201, 11, 'What is FinOps in cloud computing?', 'A software compiler for financial calculation spreadsheets', 'The operational and cultural practice that brings financial accountability to cloud spending, maximizing business value', 'A financial loan provided by cloud providers to purchase servers', 'A cryptocurrency protocol', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'FinOps (Financial Operations) unites engineering, finance, and business to optimize cloud investments and governance.'),
(202, 11, 'Which cloud purchasing model offers up to 90% discounts by allowing customers to bid on unused cloud compute capacity, with the caveat of a 2-minute interruption notice?', 'On-Demand Instances', 'Spot Instances', 'Dedicated Hosts', 'Standard Reserved Instances', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Spot Instances let you tap spare cloud compute capacity at steep discounts, provided your workload can handle sudden evictions.'),
(203, 11, 'What discount level is typically achieved by committing to a 1-year or 3-year Savings Plan or Reserved Instance?', '0% discount', 'Up to 72% discount compared to On-Demand pricing', '100% free compute forever', 'Exactly 5% discount', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Commitment-based models (Savings Plans and Reserved Instances) reward steady usage with discounts of up to ~72% over on-demand rates.'),
(204, 11, 'Which of the following workloads is LEAST suited for Spot Instances?', 'Batch image processing jobs', 'Distributed machine learning model training with checkpoints', 'A mission-critical monolithic core banking transaction database', 'Stateless container CI/CD testing runners', 'C', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Monolithic core databases cannot tolerate unexpected 2-minute terminations and must run on reliable On-Demand or Reserved capacity.'),
(205, 11, 'What is \'Rightsizing\' in cloud cost optimization?', 'Physically cutting a computer chassis to fit into a rack', 'Analyzing resource metrics to downsize over-provisioned or underutilized instances to smaller, cheaper instance types', 'Writing code with shorter variable names', 'Enforcing identical monitor resolutions across all developers', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Rightsizing matches instance types and sizes to actual performance requirements, eliminating wasted over-provisioned capacity.'),
(206, 11, 'What are Resource Tags in cloud management?', 'Physical barcode stickers affixed to datacenter doors', 'Key-value metadata assigned to cloud resources for cost allocation, ownership tracking, and automated governance', 'Graffiti spray-painted on server cases', 'HTML tags inside web page headers', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Resource tags (e.g. CostCenter: Finance, Environment: Prod) attach critical metadata for billing, automation, and access control.'),
(207, 11, 'What does Power Usage Effectiveness (PUE) measure in datacenter sustainability?', 'The typing speed of datacenter engineers', 'The ratio of total facility power consumed to the power consumed strictly by the IT computing equipment', 'The voltage delivered by municipal electrical lines', 'The volume of diesel fuel stored in emergency tanks', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'PUE (Total Facility Energy / IT Equipment Energy) quantifies datacenter energy efficiency; a ratio closer to 1.0 indicates lower wasted energy on cooling.'),
(208, 11, 'What is an ideal Power Usage Effectiveness (PUE) score representing 100% energy efficiency with zero cooling waste?', '0.0', '1.0', '10.0', '100.0', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A PUE of 1.0 represents perfect efficiency, where every watt of power entering the facility directly feeds computing hardware.');
INSERT INTO `quiz_questions` (`question_id`, `quiz_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `created_at`, `updated_at`, `explanation`) VALUES
(209, 11, 'What is a major environmental benefit of migrating from corporate on-premise data centers to hyperscale public clouds?', 'Public clouds use less total internet bandwidth', 'Hyperscalers achieve significantly higher server utilization and lower PUE, reducing enterprise computing carbon emissions by up to 80%', 'Public clouds produce zero physical heat', 'Servers never consume any electricity in the cloud', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Higher hardware consolidation ratios and advanced cooling efficiency mean public clouds require significantly less power per workload.'),
(210, 11, 'What is a Service Control Policy (SCP) in AWS Organizations?', 'A policy that defines maximum allowed permissions for accounts in an organization, functioning as a non-bypassable guardrail', 'A document detailing customer support phone numbers', 'A script that turns on office air conditioners', 'An insurance policy against computer theft', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'SCPs set permission boundaries over accounts in an AWS Organization, restricting actions even if an account administrator permits them.'),
(211, 11, 'What is the primary benefit of a Multi-Account cloud architecture (e.g. separate accounts for Dev, Staging, and Production)?', 'Limiting the \'blast radius\' so an error or security compromise in Dev cannot impact Production', 'Getting free cloud accounts from sales teams', 'Making passwords shorter', 'Allowing everyone to share the same root password', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Account separation limits blast radius, isolates billing data, simplifies audit compliance, and protects production workloads.'),
(212, 11, 'What is an orphaned or zombie cloud asset?', 'A server running video games about zombies', 'An unused cloud resource (e.g. unattached EBS volume, idle Elastic IP, obsolete snapshot) that continues accruing billing charges', 'A deleted user account', 'A broken fiber optic cable', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Zombie assets are detached storage volumes or idle IP addresses left behind after instances terminate, silently accumulating costs.'),
(213, 11, 'What is the difference between \'Chargeback\' and \'Showback\' in cloud accounting?', 'Chargeback actually bills internal departments for their cloud consumption; Showback merely provides visibility into costs without cross-charging budgets', 'Chargeback is illegal; Showback is legal', 'Chargeback only applies to credit cards; Showback applies to cash', 'There is no difference between the terms', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Showback educates teams on their cloud spend for awareness; chargeback formally transfers actual financial costs to each department\'s budget.'),
(214, 11, 'Why is scheduling development and staging servers to shut down automatically on nights and weekends a recommended FinOps practice?', 'It cools down server motherboards so they do not melt', 'Non-production environments are typically unused outside business hours; shutting them down for ~128 hours/week reduces compute costs by over 60%', 'It prevents hackers from working on weekends', 'Operating systems require 8 hours of sleep per day', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A week contains 168 hours; running dev servers only 40-50 hours during business times eliminates over 65% of unnecessary idle compute spend.'),
(215, 11, 'What is Data Sovereignty in the context of cloud ethics and compliance?', 'The principle that data is subject to the legal governance and regulatory privacy laws of the nation where it is physically located', 'The ownership of digital assets by internet service providers', 'A legal treaty allowing free public distribution of all corporate data', 'The conversion of text files into binary numbers', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Data sovereignty dictates that digital data stored in a country is governed by that country\'s local laws and judicial jurisdiction.'),
(216, 11, 'Which native AWS service inspects your environment and provides real-time recommendations to optimize cost, security, fault tolerance, and performance?', 'AWS Trusted Advisor', 'AWS IAM', 'AWS CodeCommit', 'AWS Snowball', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS Trusted Advisor reviews your AWS infrastructure against best practices and flags idle resources, security gaps, and cost savings.'),
(217, 11, 'What does the Philippine Data Privacy Act of 2012 (Republic Act No. 10173) mandate for cloud systems processing citizen data?', 'Mandates stringent protections for personal information, rights of data subjects, and compliance overseen by the National Privacy Commission (NPC)', 'Requires all servers to be located in presidential palaces', 'Bans all cloud computing across educational institutions', 'Requires paper duplicates of all digital emails', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'RA 10173 regulates the processing of personal information in the Philippines, enforcing data protection standards and breach penalties.'),
(218, 11, 'What is an AWS Budget alarm?', 'A siren that sounds in the cloud datacenter', 'A custom threshold notification that alerts administrators when cloud spend or usage exceeds (or is forecasted to exceed) predefined financial limits', 'An automatic cancellation of all company bank accounts', 'A tool that deletes expensive virtual machines without warning', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS Budgets sends proactive alerts (via email/SNS/Slack) when actual or forecasted cloud costs cross configured budget limits.'),
(219, 11, 'In the FinOps framework, what does the \'Inform\' phase focus on?', 'Terminating random servers', 'Giving visibility, allocating costs accurately via tags, and providing transparent benchmarking to engineering and finance teams', 'Filing patent lawsuits against competitors', 'Calling customer service hotlines', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'The Inform phase provides full visibility into cloud spending through tags, dashboards, and allocation metrics.'),
(220, 11, 'How does the practice of \'Green Computing\' impact software architecture decisions in the cloud?', 'It encourages efficient code algorithms, rightsized instances, and serverless architectures to minimize wasted electrical energy', 'It requires painting physical server racks with green eco-friendly paint', 'It forces all web pages to use green color schemes', 'It limits developers to writing no more than 10 lines of code per day', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Green software engineering optimizes application efficiency and rightsizes infrastructure, directly reducing energy draw and carbon output.'),
(221, 12, 'What is the primary driving motivation for adopting Edge Computing over centralized cloud computing?', 'To eliminate the need for computer monitors', 'To minimize network round-trip latency and bandwidth consumption by processing data near its generation source', 'Because edge computing is completely free of charge', 'To restrict internet access to local government officials', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Edge computing places compute and storage close to data sources (IoT, sensors, vehicles), eliminating the latency of transmitting data to distant clouds.'),
(222, 12, 'In the distributed computing continuum, what is Fog Computing?', 'Computers operating in foggy weather conditions', 'An intermediate architecture layer bridging local edge devices with the centralized hyperscale cloud for pre-processing and aggregation', 'A computer virus that blurs screen pixels', 'A hardware cooling system that sprays water vapor into servers', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Fog computing acts as the intermediate tier between edge IoT sensors and centralized clouds, handling localized data reduction and routing.'),
(223, 12, 'What AWS service places cloud compute and storage hardware directly inside telecommunications 5G network datacenters?', 'AWS Wavelength', 'AWS Snowball', 'Amazon S3 Glacier', 'AWS Elastic Beanstalk', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS Wavelength embeds AWS compute and storage services within 5G networks, providing mobile application traffic with single-digit millisecond latency.'),
(224, 12, 'What is the quantum computing equivalent of a classical computer bit?', 'Byte', 'Qubit (Quantum Bit)', 'Transistor', 'Pixel', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A Qubit is the basic unit of quantum information, capable of existing in states of superposition unlike classical binary 0 or 1 bits.'),
(225, 12, 'What quantum mechanical property enables a qubit to exist in a linear combination of states (both 0 and 1 simultaneously)?', 'Superposition', 'Virtualization', 'Fragmentation', 'Thermal throttling', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Superposition allows a quantum system to be in multiple states simultaneously until it is observed or measured.'),
(226, 12, 'What quantum phenomenon links pairs or groups of particles such that the state of one instantly dictates the state of another, regardless of distance?', 'Quantum Entanglement', 'Data Replication', 'Cache Invalidation', 'Packet Routing', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Quantum entanglement describes particles whose quantum states cannot be described independently of each other.'),
(227, 12, 'Why is quantum computing predominantly delivered as a cloud service (e.g. Amazon Braket, Azure Quantum, IBM Quantum)?', 'Quantum computers are illegal to own outside the cloud', 'Quantum processors require extreme cryogenic cooling near absolute zero (-273.15°C) and complex lab infrastructure impractical for on-premise deployments', 'Quantum algorithms only work on websites', 'Cloud providers own all quantum physics patents', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Cryogenic dilution refrigerators and precise laser/microwave controls are cost-prohibitive for standard enterprises, making cloud access ideal.'),
(228, 12, 'What is MLOps in cloud engineering?', 'Military Operations in the cloud', 'Machine Learning Operations — applying DevOps practices (CI/CD, versioning, monitoring) to automate ML model training and deployment pipelines', 'Manual typing of training datasets', 'A programming language used for robotics', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'MLOps bridges machine learning and operational software engineering to automate testing, deployment, and monitoring of ML models.'),
(229, 12, 'What is \'Model Drift\' in production machine learning systems?', 'A physical robot car losing tire traction', 'The degradation of an ML model\'s prediction accuracy over time caused by changes in real-world data distributions', 'A computer monitor slowly turning black and white', 'A developer switching between different cloud platforms', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Model drift occurs when real-world conditions diverge from training data, requiring automated retraining pipelines to restore accuracy.'),
(230, 12, 'What 5G capability provides guaranteed ultra-reliable low latency communication (<1ms) for mission-critical industrial applications?', 'URLLC (Ultra-Reliable Low-Latency Communication)', 'eMBB (Enhanced Mobile Broadband)', 'SMS Text Messaging', 'MMS Multimedia', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'URLLC is a core 5G standard engineered specifically for mission-critical use cases like autonomous transport and factory automation.'),
(231, 12, 'What is 5G Network Slicing?', 'Physically cutting cellular fiber cables with scissors', 'Virtualizing a single physical 5G network into multiple isolated logical networks with customized QoS and latency guarantees', 'Limiting users to 10 minutes of phone calls per day', 'Slicing silicon wafers into microchips', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Network slicing allows operators to divide a physical 5G network into virtual slices tailored for specific enterprise service requirements.'),
(232, 12, 'What was Microsoft Project Natick?', 'An underwater sealed datacenter research trial that proved submerged marine servers had an 8x lower failure rate', 'A flight simulator game built for Azure', 'A new search engine competing with Google', 'A satellite constellation launched into low Earth orbit', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Project Natick demonstrated that submerging sealed datacenter pods in ocean water with nitrogen atmosphere drastically boosted server reliability.'),
(233, 12, 'What is Carbon-Aware Computing in modern cloud orchestration?', 'Writing software code with dark mode enabled', 'Dynamically scheduling or migrating computing workloads to cloud regions and times when renewable energy (solar, wind) is most abundant', 'Banning the use of carbon paper in offices', 'Using charcoal filters inside desktop computers', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Carbon-aware systems shift delay-tolerant batch compute jobs to locations and times where local power grids have peak clean renewable generation.'),
(234, 12, 'Why is an autonomous vehicle reliant on Edge Computing rather than centralized cloud for emergency obstacle braking?', 'Cloud servers do not understand digital video', 'Network transmission latency over cellular links back to distant clouds is too slow to prevent high-speed collisions in real-time', 'Cars cannot connect to wireless radio frequencies', 'Centralized cloud providers forbid automotive applications', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'At high speed, a split-second latency delay could cause a fatal collision; emergency decisions must be computed on-device in real-time.'),
(235, 12, 'What specialized network fabric do cloud hyperscalers use to connect thousands of GPUs for distributed AI training with microsecond latencies?', 'Dial-up telephone modems', 'NVIDIA InfiniBand / AWS Elastic Fabric Adapter (EFA)', 'Standard consumer Wi-Fi 4', 'Coaxial TV cables', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Massive AI training clusters use high-speed RDMA fabrics like InfiniBand or AWS EFA to synchronize model weights across thousands of GPUs.'),
(236, 12, 'What is an AWS Outposts rack?', 'A camping tent for Amazon warehouse workers', 'A physical rack of AWS-designed hardware installed inside a customer\'s on-premises data center, operated natively via the AWS console', 'A wooden server case used for vintage exhibitions', 'A mailbox for physical Amazon packages', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'AWS Outposts brings native AWS infrastructure, services, and APIs to virtually any customer on-premises data center or edge facility.'),
(237, 12, 'In cloud MLOps, what is a Feature Store?', 'A retail store that sells computer graphics cards', 'A centralized repository that stores, curates, and serves standardized machine learning features for training and real-time inference', 'A digital music store for smartphone ringtones', 'A database table that lists software bugs', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'A feature store manages curated data attributes (features) to ensure consistency between offline model training and online production inference.'),
(238, 12, 'What cooling technique is replacing traditional air conditioning to support high-density 700W+ AI server racks?', 'Direct-to-chip liquid cooling and immersion liquid cooling', 'Ice cubes placed on top of server chassis', 'Opening windows in datacenter walls', 'Paper hand fans operated by staff', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Modern thermal loads generated by AI clusters exceed air cooling capacities, requiring dielectric liquid immersion or direct-to-chip cold plates.'),
(239, 12, 'What does Serverless Edge Computing (e.g. Cloudflare Workers, AWS Lambda@Edge) enable?', 'Executing lightweight code at hundreds of global CDN edge locations within 5 milliseconds of end users', 'Running Windows 98 on microwave ovens', 'Deleting all origin databases', 'Replacing all web servers with radio antennas', 'A', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Edge serverless functions execute code at global CDN points of presence, rewriting headers, personalizing content, and inspecting tokens at the edge.'),
(240, 12, 'What is the defining mindset of a modern Cloud Solutions Architect?', 'Attempting to build and maintain everything on private physical hardware', 'Designing scalable, resilient, secure, cost-optimized, and sustainable distributed systems using automated cloud building blocks', 'Memorizing only command-line shortcuts without understanding architecture', 'Avoiding all software updates and security patches', 'B', '2026-10-25 17:28:08', '2026-10-26 07:13:57', 'Cloud architects design distributed systems that continuously optimize availability, resilience, cost, security, and sustainability.');
